func (d *ExplorationDataSource) Configure(ctx context.Context, req datasource.ConfigureRequest, resp *datasource.ConfigureResponse) {
	if req.ProviderData == nil {
		return
	}
	d.client = req.ProviderData.(*Client)
}

func (d *ExplorationDataSource) Read(ctx context.Context, req datasource.ReadRequest, resp *datasource.ReadResponse) {
	var data ExplorationModel
	resp.Diagnostics.Append(req.Config.Get(ctx, &data)...)
	if resp.Diagnostics.HasError() {
		return
	}
	ctx = inTeam(ctx, data.TeamId.ValueString())
	var out map[string]interface{}
	if !data.Id.IsNull() && !data.Id.IsUnknown() && data.Id.ValueString() != "" {
		vars := map[string]string{}
		vars["id"] = data.Id.ValueString()
		got, found, err := d.client.GetDataSource(ctx, explorationBinding, vars)
		if err != nil {
			addAPIError(&resp.Diagnostics, "reading exploration", err, req.Config.Raw.Type())
			return
		}
		if !found {
			resp.Diagnostics.AddError("exploration not found", fmt.Sprintf("no exploration with id %s", data.Id.ValueString()))
			return
		}
		out = got
		if !data.ExplorationGroupId.IsNull() && !data.ExplorationGroupId.IsUnknown() && data.ExplorationGroupId.ValueString() != "" {
			matched := false
			for _, field := range []string{"exploration_group_id"} {
				if stringifyScalar(out[field]) == data.ExplorationGroupId.ValueString() {
					matched = true
					break
				}
			}
			if !matched {
				resp.Diagnostics.AddError("exploration lookup conflicts with id", "The selected object does not match configured exploration_group_id.")
				return
			}
		}
		if !data.Product.IsNull() && !data.Product.IsUnknown() && data.Product.ValueString() != "" {
			matched := false
			for _, field := range []string{"product"} {
				if stringifyScalar(out[field]) == data.Product.ValueString() {
					matched = true
					break
				}
			}
			if !matched {
				resp.Diagnostics.AddError("exploration lookup conflicts with id", "The selected object does not match configured product.")
				return
			}
		}
		if !data.Name.IsNull() && !data.Name.IsUnknown() && data.Name.ValueString() != "" {
			matched := false
			for _, field := range []string{"name"} {
				if stringifyScalar(out[field]) == data.Name.ValueString() {
					matched = true
					break
				}
			}
			if !matched {
				resp.Diagnostics.AddError("exploration lookup conflicts with id", "The selected object does not match configured name.")
				return
			}
		}
	} else {
		// Lookup by filter: narrow server-side with the filters the list endpoint declares, then
		// require an exact, unambiguous client-side match.
		vars := map[string]string{}
		q := url.Values{}
		want := map[string]string{}
		alternatives := map[string][]string{
			"exploration_group_id": {"exploration_group_id"},
			"product":              {"product"},
			"name":                 {"name"},
		}
		if !data.ExplorationGroupId.IsNull() && !data.ExplorationGroupId.IsUnknown() && data.ExplorationGroupId.ValueString() != "" {
			q.Set("exploration_group_id", data.ExplorationGroupId.ValueString())
			want["exploration_group_id"] = data.ExplorationGroupId.ValueString()
		}
		if !data.Product.IsNull() && !data.Product.IsUnknown() && data.Product.ValueString() != "" {
			q.Set("product", data.Product.ValueString())
			want["product"] = data.Product.ValueString()
		}
		if !data.Name.IsNull() && !data.Name.IsUnknown() && data.Name.ValueString() != "" {
			want["name"] = data.Name.ValueString()
		}
		if len(want) == 0 {
			resp.Diagnostics.AddError("missing exploration lookup", "Set id or one of: exploration_group_id, product, name.")
			return
		}
		records, err := d.client.List(ctx, explorationBinding, vars, q)
		if err != nil {
			addAPIError(&resp.Diagnostics, "reading exploration", err, req.Config.Raw.Type())
			return
		}
		var matches []map[string]interface{}
		for _, rec := range records {
			ok := true
			for k, v := range want {
				matched := false
				for _, field := range alternatives[k] {
					if stringifyScalar(rec[field]) == v {
						matched = true
						break
					}
				}
				if !matched {
					ok = false
					break
				}
			}
			if ok {
				matches = append(matches, rec)
			}
		}
		if len(matches) == 0 {
			resp.Diagnostics.AddError("exploration not found", "no exploration matched the lookup attributes")
			return
		}
		if len(matches) > 1 {
			resp.Diagnostics.AddError("exploration lookup is ambiguous", fmt.Sprintf("%d exploration records matched; look up by id instead", len(matches)))
			return
		}
		out = matches[0]
		data.Id = types.StringValue(stringifyScalar(out["id"]))
		// List endpoints may return summaries. Resolve the selected identity through the real
		// member endpoint so computed outputs and data-source-only reads are complete.
		memberVars := map[string]string{}
		memberVars["id"] = data.Id.ValueString()
		detail, found, err := d.client.GetDataSource(ctx, explorationBinding, memberVars)
		if err != nil {
			addAPIError(&resp.Diagnostics, "reading exploration details", err, req.Config.Raw.Type())
			return
		}
		if !found {
			resp.Diagnostics.AddError("exploration not found", "The selected object disappeared before its detail could be read.")
			return
		}
		out = detail
	}
	populateExploration(ctx, &data, out)
	resp.Diagnostics.Append(resp.State.Set(ctx, &data)...)
}
